import pytest
from main import get_content_type


class MockResponse:
    def __init__(self, headers: dict[str, str]) -> None:
        self.headers = headers


run_cases = [
    pytest.param(
        {
            "Content-Type": "application/json",
            "Authorization": "Bearer token123",
        },
        "application/json",
        id="json",
    ),
    pytest.param(
        {"Content-Type": "text/html", "Accept-Language": "en-US"},
        "text/html",
        id="html",
    ),
]

submit_cases = [
    pytest.param(
        {"Authorization": "Bearer token123"},
        "",
        marks=pytest.mark.submit,
        id="missing-content-type",
    ),
    pytest.param(
        {
            "Content-Type": "application/xml",
            "Cache-Control": "no-cache",
        },
        "application/xml",
        marks=pytest.mark.submit,
        id="xml",
    ),
]


@pytest.mark.parametrize(("headers", "expected"), run_cases + submit_cases)
def test_get_content_type(headers, expected):
    print("\n---------------------------------")
    print(f"Headers: {headers}")
    print(f"Expected: {expected}")
    response = MockResponse(headers)
    result = get_content_type(response)
    print(f"Actual:   {result}")
    assert result == expected

