import random
from typing import TypedDict

from pyodide.http import pyfetch


class UserProfile(TypedDict):
    name: str


class User(TypedDict):
    experience: int
    user: UserProfile


async def get_users(url: str, api_key: str) -> list[User]:
    full_url = url
    response = await pyfetch(
        full_url,
        method="GET",
        headers={
            "X-API-Key": api_key,
        },
    )
    return await response.json()


# don't touch below this line


def generate_key() -> str:
    characters = "ABCDEF0123456789"
    result = ""
    for _ in range(16):
        result += characters[random.randint(0, len(characters) - 1)]
    return result


base_url = "https://api.boot.dev/v1/courses_rest_api/learn-http/users"

api_key = generate_key()

users = await get_users(base_url, api_key)
for user in users:
    print(
        f"got user with name: {user['user']['name']}, "
        f"and experience: {user['experience']}"
    )
